begin;
-- Exercise the future capture session boundary directly; capture launch is still blocked.
do $$ declare
 tenant uuid:='10000000-0000-4000-8000-000000000001';owner uuid:='00000000-0000-4000-8000-000000000001';candidate uuid:='00000000-0000-4000-8000-000000000003';foreign_user uuid:='00000000-0000-4000-8000-000000000004';reviewer uuid:='00000000-0000-4000-8000-000000000006';
 win uuid;reg uuid;aid uuid;sid uuid;pol uuid;version_id uuid;rid uuid:=gen_random_uuid();expired_rid uuid:=gen_random_uuid();foreign_rid uuid:=gen_random_uuid();cid uuid;fid uuid;result jsonb;data jsonb;part_grant jsonb;form jsonb;head text;receipt jsonb;finding_data jsonb;
begin
 select id into version_id from assessment_versions limit 1;select manifest into form from assessment_forms limit 1;
 result:=pg_temp.assessment_command(owner,tenant,'recording-window-001','window.create',jsonb_build_object('assessment_version_id',version_id,'title','Recording fixture','opens_at',now()-interval '1 hour','closes_at',now()+interval '1 hour'));win:=(result->>'id')::uuid;
 result:=pg_temp.assessment_command(owner,tenant,'recording-registration-001','registration.create',jsonb_build_object('window_id',win,'candidate_id',candidate));reg:=(result->>'id')::uuid;
 result:=pg_temp.assessment_command(candidate,tenant,'recording-attempt-001','attempt.start',jsonb_build_object('registration_id',reg,'manifest',form,'manifest_hash',repeat('a',64)));aid:=(result->>'id')::uuid;
 update assessment_attempts set deadline_at=clock_timestamp()+interval '1 hour',section_deadline_at=clock_timestamp()+interval '1 hour' where id=aid;
 result:=proctor_command(owner,tenant,'recording-policy-001','policy.create','{"title":"Recording policy fixture","policy":{"schema_version":"proctor.policy.v1","mode":"browser","identity_level":0,"camera":true,"microphone":false,"screen":true,"second_camera":false,"reviewer_quorum":2}}');pol:=(result->>'id')::uuid;
 insert into proctor_sessions(tenant_id,attempt_id,candidate_id,policy_id,policy_snapshot) select tenant,aid,candidate,id,policy from proctor_policies where id=pol returning id into sid;
 data:=jsonb_build_object('recording_id',rid,'session_id',sid,'source','camera','mime','video/webm');
 begin perform proctor_recording_command(candidate,tenant,'recording-no-consent','recording.begin',data);raise exception 'Recording without consent accepted';exception when check_violation then null;end;
 insert into proctor_preparations(tenant_id,registration_id,candidate_id,policy_id) values(tenant,reg,candidate,pol);
 begin perform proctor_recording_command(foreign_user,tenant,'recording-foreign','recording.begin',data);raise exception 'Foreign candidate recorded session';exception when no_data_found then null;end;
 begin perform proctor_recording_command(candidate,tenant,'recording-forbidden-source','recording.begin',data||'{"source":"microphone","mime":"audio/webm"}');raise exception 'Unconsented source recorded';exception when invalid_parameter_value then null;end;
 result:=proctor_recording_command(candidate,tenant,'recording-begin-001','recording.begin',data);
 if result<>proctor_recording_command(candidate,tenant,'recording-begin-001','recording.begin',data) then raise exception 'Recording begin replay changed';end if;
 begin perform proctor_recording_command(candidate,tenant,'recording-second-open','recording.begin',data||jsonb_build_object('recording_id',gen_random_uuid()));raise exception 'Multiple active camera streams accepted';exception when unique_violation then null;end;
 data:=jsonb_build_object('recording_id',rid,'sequence',1,'start_ms',0,'end_ms',5000,'previous_hash',repeat('0',64),'byte_length',3,'sha256',repeat('a',64),'parts',jsonb_build_array(jsonb_build_object('byte_length',3,'sha256',repeat('a',64))));
 begin perform proctor_recording_command(candidate,tenant,'recording-fraction','recording.reserve',data||'{"sequence":1.5}');raise exception 'Fractional sequence accepted';exception when unique_violation then null;end;
 begin perform proctor_recording_command(candidate,tenant,'recording-part-invalid','recording.reserve',data||'{"parts":[{"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","byte_length":2}]}');raise exception 'Wrong part size accepted';exception when invalid_parameter_value then null;end;
 result:=proctor_recording_command(candidate,tenant,'recording-reserve-001','recording.reserve',data);head:=result->>'head_hash';
 if result<>proctor_recording_command(candidate,tenant,'recording-reserve-001','recording.reserve',data) then raise exception 'Reserve lost-reply replay changed';end if;
 begin perform proctor_recording_transport(candidate,tenant,'segment.complete',jsonb_build_object('recording_id',rid,'sequence',1));raise exception 'Incomplete recording committed';exception when check_violation then null;end;
 begin perform proctor_recording_command(candidate,tenant,'recording-close-pending','recording.close',jsonb_build_object('recording_id',rid,'expected_sequence',1,'expected_hash',head,'reason','runtime_end'));raise exception 'Pending recording sealed';exception when check_violation then null;end;
 part_grant:=proctor_recording_transport(candidate,tenant,'part.authorize',jsonb_build_object('recording_id',rid,'sequence',1,'index',0));
 if part_grant->>'tenant_id'<>tenant::text or part_grant->>'sha256'<>repeat('a',64) then raise exception 'Recording transport scope differs';end if;
 receipt:=jsonb_build_object('recording_id',rid,'sequence',1,'index',0,'sha256',repeat('a',64),'byte_length',3,'cipher_sha256',repeat('b',64),'iv',repeat('c',24),'key_id','test-k1','etag','etag-1','object_key','forged');
 perform proctor_recording_transport(candidate,tenant,'part.receipt',receipt);perform proctor_recording_transport(candidate,tenant,'part.receipt',receipt);
 if (select object_key from proctor_recording_parts where recording_id=rid)<>('proctor/'||tenant::text||'/'||rid::text||'/1/0/'||repeat('a',64)) then raise exception 'Client selected evidence storage identity';end if;
 begin perform proctor_recording_transport(candidate,tenant,'part.receipt',receipt||'{"etag":"replacement"}');raise exception 'Canonical evidence receipt replaced';exception when unique_violation then null;end;
 perform proctor_recording_transport(candidate,tenant,'segment.complete',jsonb_build_object('recording_id',rid,'sequence',1));perform proctor_recording_transport(candidate,tenant,'segment.complete',jsonb_build_object('recording_id',rid,'sequence',1));
 begin perform proctor_recording_command(candidate,tenant,'recording-silent-hole','recording.gap',jsonb_build_object('recording_id',rid,'sequence',2,'start_ms',6000,'end_ms',7000,'previous_hash',head,'reason','Unreported interval'));raise exception 'Silent interval gap accepted';exception when invalid_parameter_value then null;end;
 result:=proctor_recording_command(candidate,tenant,'recording-gap-001','recording.gap',jsonb_build_object('recording_id',rid,'sequence',2,'start_ms',5000,'end_ms',7000,'previous_hash',head,'reason','Screen/camera capture stopped during reconnect'));head:=result->>'head_hash';
 begin perform proctor_recording_transport(candidate,tenant,'segment.read',jsonb_build_object('recording_id',rid,'sequence',1));raise exception 'Candidate acquired reviewer playback';exception when no_data_found then null;end;
 begin perform proctor_recording_read(reviewer,tenant,rid);raise exception 'Unassigned reviewer read evidence';exception when no_data_found then null;end;
 perform proctor_command(owner,tenant,'recording-reviewer-001','session.assign',jsonb_build_object('session_id',sid,'user_id',reviewer,'assignment_role','reviewer'));
 result:=proctor_recording_read(reviewer,tenant,rid,0,1);
 if encode(sha256(convert_to(result->'segments'->0->>'chain_entry','UTF8')),'hex')<>result->'segments'->0->>'chain_hash' then raise exception 'Reviewer chain payload differs from canonical hash';end if;
 if (proctor_recording_checkpoint(candidate,tenant,rid,1)->'segment'->>'state')<>'committed' then raise exception 'Candidate cannot reconcile its committed media';end if;
 if proctor_recording_checkpoint(candidate,tenant,rid,1)::text like '%object_key%' or proctor_recording_checkpoint(candidate,tenant,rid,1)::text like '%cipher_sha256%' then raise exception 'Candidate checkpoint leaked playback/storage envelopes';end if;
 begin perform proctor_recording_checkpoint(owner,tenant,rid,1);raise exception 'Staff acquired candidate recovery checkpoint';exception when no_data_found then null;end;
 if (proctor_recording_catalog(reviewer,tenant,sid)->'items'->0->>'id')<>rid::text then raise exception 'Assigned reviewer cannot discover recording manifest';end if;
 if result->>'next_cursor'<>'1' or jsonb_array_length(result->'segments')<>1 or result->'recording'->>'provenance'<>'browser_reported' then raise exception 'Recording pagination/provenance differs';end if;
 if (proctor_recording_read(reviewer,tenant,rid,1,1)->'segments'->0->>'kind')<>'gap' then raise exception 'Explicit gap lost from review';end if;
 perform proctor_recording_transport(reviewer,tenant,'segment.read',jsonb_build_object('recording_id',rid,'sequence',1));
 update proctor_assignments set active=false where session_id=sid and user_id=reviewer;
 begin perform proctor_recording_catalog(reviewer,tenant,sid);raise exception 'Revoked reviewer discovered recordings';exception when no_data_found then null;end;
 begin perform proctor_recording_transport(reviewer,tenant,'segment.read',jsonb_build_object('recording_id',rid,'sequence',1));raise exception 'Revoked reviewer read playback';exception when no_data_found then null;end;
 begin perform proctor_recording_command(candidate,tenant,'recording-close-wrong','recording.close',jsonb_build_object('recording_id',rid,'expected_sequence',1,'expected_hash',head,'reason','runtime_end'));raise exception 'Stale recording sealed';exception when unique_violation then null;end;
 perform proctor_recording_command(candidate,tenant,'recording-close-001','recording.close',jsonb_build_object('recording_id',rid,'expected_sequence',2,'expected_hash',head,'reason','runtime_end'));
 -- Citations and finding/quorum transitions must be one retry-safe transaction.
 perform proctor_command(owner,tenant,'citation-reviewer-restore','session.assign',jsonb_build_object('session_id',sid,'user_id',reviewer,'assignment_role','reviewer'));
 result:=proctor_command(owner,tenant,'citation-case-open','case.create',jsonb_build_object('session_id',sid,'title','Recording interval review'));cid:=(result->>'id')::uuid;
 finding_data:=jsonb_build_object('case_id',cid,'disposition','insufficient_evidence','rationale','The saved footage and explicit gap do not establish a misconduct finding.','evidence_event_ids','[]'::jsonb,'evidence_recording_refs',jsonb_build_array(jsonb_build_object('recording_id',rid,'from_sequence',1,'to_sequence',2,'head_hash',head)));
 begin perform proctor_command(reviewer,tenant,'citation-wrong-head','case.finding',jsonb_set(finding_data,'{evidence_recording_refs,0,head_hash}',to_jsonb(repeat('f',64))));raise exception 'Unreviewed recording head cited';exception when unique_violation then null;end;
 begin perform proctor_command(reviewer,tenant,'citation-wrong-range','case.finding',jsonb_set(finding_data,'{evidence_recording_refs,0,to_sequence}','3'));raise exception 'Missing recording interval cited';exception when check_violation then null;end;
 begin perform proctor_command(reviewer,tenant,'citation-fractional','case.finding',jsonb_set(finding_data,'{evidence_recording_refs,0,from_sequence}','1.5'));raise exception 'Fractional citation sequence rounded';exception when invalid_parameter_value then null;end;
 insert into proctor_recordings(id,tenant_id,session_id,candidate_id,source,mime,state,sealed_at) select foreign_rid,tenant,id,candidate,'camera','video/webm','sealed',clock_timestamp() from proctor_sessions where tenant_id=tenant and id<>sid limit 1;
 begin perform proctor_command(reviewer,tenant,'citation-foreign-session','case.finding',jsonb_set(finding_data,'{evidence_recording_refs,0,recording_id}',to_jsonb(foreign_rid)));raise exception 'Other session footage cited';exception when check_violation then null;end;
 if exists(select 1 from proctor_case_findings where case_id=cid) or (select state from proctor_review_cases where id=cid)<>'open' then raise exception 'Invalid citations partially saved finding/quorum';end if;
 result:=proctor_command(reviewer,tenant,'citation-finding-001','case.finding',finding_data);fid:=(result->>'id')::uuid;
 if proctor_command(reviewer,tenant,'citation-finding-001','case.finding',finding_data)<>result then raise exception 'Citation lost-reply replay changed';end if;
 if (select count(*) from proctor_recording_citations where finding_id=fid)<>1 or (select media_count from proctor_recording_citations where finding_id=fid)<>1 or (select gap_count from proctor_recording_citations where finding_id=fid)<>1 then raise exception 'Citation snapshot lost media/gap distinction';end if;
 if (select recording_head_hash from proctor_recording_citations where finding_id=fid)<>head or (select to_chain_hash from proctor_recording_citations where finding_id=fid)<>head then raise exception 'Citation receipts not pinned';end if;
 begin update proctor_recording_citations set gap_count=0 where finding_id=fid;raise exception 'Permanent citation erased gap';exception when check_violation then null;end;
 begin perform proctor_command(reviewer,tenant,'citation-finding-001','case.finding',jsonb_set(finding_data,'{evidence_recording_refs,0,to_sequence}','1'));raise exception 'Same finding key changed citation';exception when unique_violation then null;end;
 update proctor_assignments set active=false where session_id=sid and user_id=reviewer;
 begin perform proctor_command(reviewer,tenant,'citation-finding-001','case.finding',finding_data);raise exception 'Revoked reviewer retained finding replay authority';exception when insufficient_privilege then null;end;
 perform proctor_command(owner,tenant,'citation-finding-independent','case.finding',finding_data||jsonb_build_object('rationale','Independent human review agrees that the cited media and missing interval are insufficient.'));
 if (select state from proctor_review_cases where id=cid)<>'resolved' or (select disposition from proctor_review_cases where id=cid)<>'insufficient_evidence' then raise exception 'Independent citation reviews did not preserve quorum';end if;
 if exists(select 1 from assessment_score_revisions where attempt_id=aid) then raise exception 'Recording citations changed academic grades';end if;
 if (select count(*) from assessment_audit_events where target_id=fid and action='proctor.recording.cited')<>1 then raise exception 'Citation replay duplicated audit';end if;
 begin update proctor_recording_segments set reason='Erased gap' where recording_id=rid and sequence=2;raise exception 'Evidence gap replaced';exception when check_violation then null;end;
 begin update proctor_recordings set head_hash=repeat('f',64) where id=rid;raise exception 'Sealed evidence replaced';exception when check_violation then null;end;
 if (select count(*) from assessment_audit_events where target_id=rid and action='proctor.recording.segment.committed')<>1 then raise exception 'Commit retry duplicated audit';end if;
 insert into proctor_recordings(id,tenant_id,session_id,candidate_id,source,mime,created_at,expires_at) values(expired_rid,tenant,sid,candidate,'camera','video/webm',clock_timestamp()-interval '91 days',clock_timestamp()-interval '1 second');
 result:=proctor_recording_catalog(owner,tenant,sid,null,1);if jsonb_array_length(result->'items')<>1 or result->>'next_cursor' is null then raise exception 'Recording catalog keyset paging lost cursor';end if;
 data:=proctor_recording_catalog(owner,tenant,sid,(result->>'next_cursor')::uuid,1);if jsonb_array_length(data->'items')<>1 or data->'items'->0->>'id'=result->'items'->0->>'id' then raise exception 'Recording catalog page repeated item';end if;
 begin perform proctor_recording_read(owner,tenant,expired_rid);raise exception 'Expired recording remained readable';exception when check_violation then null;end;
 begin perform proctor_recording_command(candidate,tenant,'recording-close-expired','recording.close',jsonb_build_object('recording_id',expired_rid,'expected_sequence',0,'expected_hash',repeat('0',64),'reason','runtime_end'));raise exception 'Expired recording accepted new commands';exception when check_violation then null;end;
 -- The new recording data plane must not weaken the existing capture launch guard.
 result:=pg_temp.assessment_command(owner,tenant,'recording-gated-window','window.create',jsonb_build_object('assessment_version_id',version_id,'title','Capture launch remains gated','opens_at',now()-interval '1 hour','closes_at',now()+interval '1 hour'));win:=(result->>'id')::uuid;
 result:=pg_temp.assessment_command(owner,tenant,'recording-gated-registration','registration.create',jsonb_build_object('window_id',win,'candidate_id',candidate));reg:=(result->>'id')::uuid;
 perform proctor_command(owner,tenant,'recording-gated-policy','policy.attach',jsonb_build_object('window_id',win,'policy_id',pol));
 perform proctor_command(candidate,tenant,'recording-gated-consent','preparation.accept',jsonb_build_object('registration_id',reg,'policy_id',pol,'acknowledged',true));
 begin perform pg_temp.assessment_command(candidate,tenant,'recording-gated-start','attempt.start',jsonb_build_object('registration_id',reg,'manifest',form,'manifest_hash',repeat('a',64)));raise exception 'Unconnected capture workflow launched';exception when check_violation or insufficient_privilege then null;end;
 if has_function_privilege('authenticated','public.proctor_recording_transport(uuid,uuid,text,jsonb)','EXECUTE') or has_function_privilege('authenticated','public.proctor_recording_candidate(uuid,uuid,uuid)','EXECUTE') then raise exception 'Browser bypasses recording authority';end if;
 if has_function_privilege('service_role','public.proctor_without_recording_citations(uuid,uuid,text,text,jsonb)','EXECUTE') then raise exception 'Service role bypasses citation validation';end if;
end; $$;
set role authenticated;
do $$ begin begin perform * from proctor_recording_parts;raise exception 'Raw evidence leaked';exception when insufficient_privilege then null;end;begin perform * from proctor_recording_citations;raise exception 'Raw recording citations leaked';exception when insufficient_privilege then null;end;end; $$;
reset role;
rollback;
